class Solution:
    def mergeTriplets(self, triplets: List[List[int]], target: List[int]) -> bool:
        cur = None
        improved = True
        while improved:
            improved = False
            for t in triplets:
                if t[0] > target[0] or t[1] > target[1] or t[2] > target[2]:
                    continue
                if cur is None:
                    cur = t[:]
                    improved = True
                    continue
                for k in range(3):
                    if t[k] > cur[k]:
                        cur[k] = t[k]
                        improved = True
            if cur == target:
                return True
        return False

