class Solution {
public:
    bool mergeTriplets(vector<vector<int>>& triplets, vector<int>& target) {
        vector<int> cur;
        bool improved = true;
        while (improved) {
            improved = false;
            for (auto& t : triplets) {
                if (t[0] > target[0] || t[1] > target[1] || t[2] > target[2]) continue;
                if (cur.empty()) { cur = t; improved = true; continue; }
                for (int k = 0; k < 3; ++k)
                    if (t[k] > cur[k]) { cur[k] = t[k]; improved = true; }
            }
            if (!cur.empty() && cur == target) return true;
        }
        return false;
    }
};

