class Solution {
    public boolean mergeTriplets(int[][] triplets, int[] target) {
        int[] cur = null;
        boolean improved = true;
        while (improved) {
            improved = false;
            for (int[] t : triplets) {
                if (t[0] > target[0] || t[1] > target[1] || t[2] > target[2]) continue;
                if (cur == null) { cur = t.clone(); improved = true; continue; }
                for (int k = 0; k < 3; k++)
                    if (t[k] > cur[k]) { cur[k] = t[k]; improved = true; }
            }
            if (cur != null && Arrays.equals(cur, target)) return true;
        }
        return false;
    }
}

