        improved = false;
        for (const t of triplets) {
            if (t[0] > target[0] || t[1] > target[1] || t[2] > target[2]) continue;
            if (!cur) { cur = [...t]; improved = true; continue; }
            for (let k = 0; k < 3; k++)
                if (t[k] > cur[k]) { cur[k] = t[k]; improved = true; }
        }
        if (cur && cur[0] === target[0] && cur[1] === target[1] && cur[2] === target[2]) return true;
    }
    return false;
};

