class Solution:
    def mergeTriplets(self, triplets: List[List[int]], target: List[int]) -> bool:
        found = set()
        for a, b, c in triplets:
            if a <= target[0] and b <= target[1] and c <= target[2]:
                if a == target[0]:
                    found.add(0)
                if b == target[1]:
                    found.add(1)
                if c == target[2]:
                    found.add(2)
        return len(found) == 3

