            if (t[0] > target[0] || t[1] > target[1] || t[2] > target[2]) continue;
            fx |= (t[0] == target[0]);
            fy |= (t[1] == target[1]);
            fz |= (t[2] == target[2]);
        }
        return fx && fy && fz;
